def maxProfit(prices):
    if not prices:
        return 0

    max_profit = 0
    max_trading_profit = float('-inf')

    for i in range(1, len(prices)):
        # First transaction
        current_price = prices[i]
        if current_price < min_price:
            min_price = current_price
        if current_price > max_price:
            max_price = current_price
            max_profit = max_profit + (current_price - min_price)
            if max_profit > max_trading_profit:
                max_trading_profit = max_profit

        # Second transaction
        if max_profit > 0 and max_trading_profit < (max_profit + (current_price - min_price)):
            max_trading_profit = max_profit + (current_price - min_price)

    return max_trading_profit if max_trading_profit > 0 else 0
```

